#!/usr/bin/env python3
"""Instala ou atualiza BXbox Cloud TV 0.7.0 na raiz do seu repositório."""
import argparse,base64,hashlib,io,zipfile
from pathlib import Path
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('--sem-workflow',action='store_true',help='preservar o workflow atual')
parser.add_argument('--substituir',action='store_true',help='substituir arquivos do aplicativo; revise alterações próprias')
args=parser.parse_args()
DATA=""""""
data=base64.b64decode(DATA)
assert hashlib.sha256(data).hexdigest()=="5d2e40e976050024ae689a715d45eb4a3c9501dd62d1ef1ca5e9d8663856ec6d", "Instalador alterado"
root=Path.cwd().resolve()
with zipfile.ZipFile(io.BytesIO(data)) as archive:
    items=[]
    for info in archive.infolist():
        path=Path(info.filename)
        if args.sem_workflow and path.parts[0]=='.github':continue
        target=(root/path).resolve()
        if path.is_absolute() or root not in target.parents:raise SystemExit('Caminho inválido no pacote')
        body=archive.read(info)
        if target.exists() and target.read_bytes()!=body and not args.substituir:raise SystemExit(f'{path} já existe. Para atualizar, revise suas mudanças e use --substituir.')
        items.append((target,body))
    obsolete=(root/'app/src/main/res/drawable/banner.xml').resolve()
    if root not in obsolete.parents:raise SystemExit('Caminho de migração inválido')
    if obsolete.is_file():
        if not args.substituir:raise SystemExit('Use --substituir para migrar o banner antigo.')
        obsolete.unlink()
    for target,body in items:
        target.parent.mkdir(parents=True,exist_ok=True)
        target.write_bytes(body)
(root/'gradlew').chmod(0o755)
print(f'Pronto: BXbox Cloud TV 0.7.0, {len(items)} arquivos gravados.')
print('Revise as mudanças; execute git add ., git commit e git push conforme o guia.')
